function APR.map:UpdateMinimapLine()
    if not self.minimapSegments then return end
    if
        not APR.settings.profile.enableAddon
        or not APR.settings.profile.showMiniMapLine
        or not APR:IsInstanceWithUI()
    then
        self:RemoveMinimapLine()
        return
    end
    local player = PlayerPoint()
    if not player or not mapRadius or mapRadius <= 0 then
        self:RemoveMinimapLine()
        return
    end
    minimapWidth, minimapHeight = Minimap:GetWidth() / 2, Minimap:GetHeight() / 2
    local facing = 0
    if rotateMinimap then facing = GetPlayerFacing() end
    if facing == nil then
        self:RemoveMinimapLine()
        return
    end
    local points = DisplayPoints()
    local cache = self.minimapRenderCache
    -- Preview points are immutable until the route or guidance cursor changes.
    -- A stationary character needs no projection, clipping or line iteration.
    if
        cache
        and cache.points == points
        and cache.x == player.Coord.x
        and cache.y == player.Coord.y
        and cache.instanceID == player.instanceID
        and cache.playerMapID == player.uiMapID
        and cache.geometryRevision == APR.navigationGeometryRevision
        and cache.projectionData == APR.NavigationData
        and cache.projectionPositions == (APR.NavigationData and APR.NavigationData.positions)
        and cache.projectionRevision == (APR.navigationPreview and APR.navigationPreview.projectionRevision)
        and cache.facing == facing
        and cache.radius == mapRadius
        and cache.width == minimapWidth
        and cache.height == minimapHeight
        and cache.shape == minimapShape
        and (not cache.retryAt or (GetTime and GetTime() or 0) < cache.retryAt)
    then
        return
    end
    cache = cache or {}
    self.minimapRenderCache = cache
    cache.retryAt = nil
    cache.points, cache.x, cache.y, cache.instanceID, cache.playerMapID =
        points, player.Coord.x, player.Coord.y, player.instanceID, player.uiMapID
    cache.facing, cache.radius, cache.width, cache.height, cache.shape =
        facing, mapRadius, minimapWidth, minimapHeight, minimapShape
    cache.geometryRevision = APR.navigationGeometryRevision
    cache.projectionData, cache.projectionPositions =
        APR.NavigationData, APR.NavigationData and APR.NavigationData.positions
    local sin, cos = math.sin(facing), math.cos(facing)
    local previous, used, projected, previousX, previousY = player, 0, false
    local active = APR.navigation and APR.navigation.GetActiveStep and APR.navigation:GetActiveStep()
    local renderedWalk
    local connections = ConnectionMask(points)
    for index, point in ipairs(points) do
        if
            not point.estimated and ((index == 1 and Connects(previous, point)) or (index > 1 and connections[index]))
        then
            if not projected then
                previousX, previousY = ProjectMinimap(previous, player, sin, cos, mapRadius, cache)
            end
            local ax, ay = previousX, previousY
            local bx, by = ProjectMinimap(point, player, sin, cos, mapRadius, cache)
            previousX, previousY, projected = bx, by, true
            if ax and bx then
                if APR.navigationPreview then
                    ax, ay, bx, by = APR.navigationPreview:ClipMinimapSegment(ax, ay, bx, by, minimapShape)
                else
                    local length = math.sqrt(bx * bx + by * by)
                    if length > 0.9 then
                        bx, by = bx / length * 0.9, by / length * 0.9
                    end
                end
                if ax then
                    used = used + 1
                    DrawSegment(
                        self.minimapSegments,
                        used,
                        ax * minimapWidth,
                        ay * minimapHeight,
                        bx * minimapWidth,
                        by * minimapHeight,
                        nil,
                        point.guideContinuation
                    )
                    if active and point.walkStep == active and (ax ~= bx or ay ~= by) then renderedWalk = active end
                end
            end
        else
            projected = false
        end
        previous = point
    end
    HideUnused(self.minimapSegments, used)
    if renderedWalk and APR.navigation.MarkGuidanceSurface then
        APR.navigation:MarkGuidanceSurface("Minimap", renderedWalk)
    end
