                                self.worldSegments,
                                used,
                                ax + dx * first,
                                ay + dy * first,
                                ax + dx * last,
                                ay + dy * last,
                                thickness,
                                true,
                                true
                            )
                        end
                    else
                        used = used + 1
                        DrawSegment(self.worldSegments, used, ax, ay, bx, by, thickness, point.guideContinuation)
