                    end
                end
            end
        else
            projected = false
        end
        previous = point
    end
    HideUnused(self.worldSegments, used)
    if renderedWalk and APR.navigation.MarkGuidanceSurface then
        APR.navigation:MarkGuidanceSurface("WorldMap", renderedWalk)
    end
